```c
/****************************************************************************
 * Name: camenc_ws_fds
 *
 * Description:
 *   Say which sockets the caller should wait on.
 *
 *   A listening socket is always worth waiting on, and so is a client's:
 *   a client sends its handshake and then whatever the page's controls
 *   send, and it is also how the server notices one that has gone away.
 *   Writability is asked for only when there is something queued for that
 *   client, because a socket that is writable with nothing to write wakes
 *   the loop for nothing.
 *
 ****************************************************************************/

int camenc_ws_fds(FAR struct camenc_ws_s *ws, FAR struct pollfd *fds, int max)
{
  int n = 0;
  int i;

  if (ws == NULL || ws->listen_fd < 0)
    {
      return 0;
    }

  if (n < max)
    {
      fds[n].fd = ws->listen_fd;
      fds[n].events = POLLIN;
      fds[n].revents = 0;
      n++;
    }

  for (i = 0; i < CAMENC_WS_MAX_CLIENTS && n < max; i++)
    {
      FAR struct camenc_ws_client_s *c = &ws->clients[i];

      if (c->fd < 0)
        {
          continue;
        }

      fds[n].fd = c->fd;
      fds[n].events = POLLIN;
      if (c->tx_len > c->tx_sent)
        {
          fds[n].events |= POLLOUT;
        }

      fds[n].revents = 0;
      n++;
    }

  return n;
}

/****************************************************************************
 * Name: ws_client_for
 *
 * Description:
 *   The client a descriptor belongs to, or NULL.
 *
 *   Looked up rather than remembered by position, because the caller's array
 *   is built before the wait and consumed after it, and a descriptor is what
 *   the two ends of that have in common.  There are at most four clients.
 *
 ****************************************************************************/

static FAR struct camenc_ws_client_s *ws_client_for(FAR struct camenc_ws_s *ws,
                                                    int fd)
{
  int i;

  for (i = 0; i < CAMENC_WS_MAX_CLIENTS; i++)
    {
      if (ws->clients[i].fd == fd)
        {
          return &ws->clients[i];
        }
    }

  return NULL;
}

/****************************************************************************
 * Name: camenc_ws_ready
 *
 * Description:
 *   Act on the sockets that became ready.
 *
 *   The array is the one camenc_ws_fds() filled, with poll()'s answer in it.
 *   A connection is taken here rather than waited for: a socket that
 *   arrived while the loop was busy sits in the backlog until this runs,
 *   which is what CONFIG_NET_TCPBACKLOG is for and what the module's header
 *   says about accept().
 *
 ****************************************************************************/

void camenc_ws_ready(FAR struct camenc_ws_s *ws, FAR struct pollfd *fds, int n)
{
  struct sockaddr_in addr;
  socklen_t alen;
  int i;

  if (ws == NULL || ws->listen_fd < 0)
    {
      return;
    }

  for (i = 0; i < n; i++)
    {
      FAR struct camenc_ws_client_s *c;

      if (fds[i].revents == 0)
        {
          continue;
        }

      if (fds[i].fd == ws->listen_fd)
        {
          /* Take whatever is waiting.  Non-blocking, so this is one accept
           * per connection and never a wait.
           */

          for (;;)
            {
              int fd;
              int slot;

              alen = sizeof(addr);
              fd = accept(ws->listen_fd, (FAR struct sockaddr *)&addr, &alen);

              if (fd < 0)
                {
                  break;
                }

              for (slot = 0; slot < CAMENC_WS_MAX_CLIENTS; slot++)
                {
                  if (ws->clients[slot].fd < 0)
                    {
                      break;
                    }
                }

              if (slot == CAMENC_WS_MAX_CLIENTS)
                {
                  _warn("CAMENC WS: no room for another client\n");
                  close(fd);
                  continue;
                }

              if (fcntl(fd, F_SETFL, fcntl(fd, F_GETFL, 0) | O_NONBLOCK) < 0)
                {
                  _err("CAMENC WS: the connection will not go non-blocking:"
                       " %d\n", errno);
                  close(fd);
                  continue;
                }

              /* Reset the connection's state, field by field.
               *
               * Not with memset: the slot owns its transmit buffer, which
               * was allocated when the server started and is meant to
               * outlive any one connection.  Clearing the whole struct
               * would throw that pointer away and leave the next write
               * going to address zero.
               */

              {
                FAR struct camenc_ws_client_s *fresh = &ws->clients[slot];

                fresh->fd = fd;
                fresh->upgraded = false;
                fresh->closing = false;
                fresh->have_init = false;
                fresh->waiting = false;
                fresh->sent = 0;
                fresh->skipped = 0;
                fresh->rx_len = 0;
                fresh->tx_len = 0;
                fresh->tx_sent = 0;

                /* The receive buffer too, not just its length.  A request
                 * is parsed as a string, so a byte left from the last
                 * connection is a byte this one did not send -- and a
                 * header it does not have can be found in it.
                 */

                memset(fresh->rx, 0, sizeof(fresh->rx));
              }

              _info("CAMENC WS: client %d connected\n", slot);
            }

          continue;
        }

      c = ws_client_for(ws, fds[i].fd);
      if (c == NULL)
        {
          continue;
        }

      /* A hangup is read for, not acted on directly: the read is what finds
       * the end of the stream, and it is also where a client that has gone
       * away is dropped.  See ws_read_client().
       */

      if ((fds[i].revents & (POLLIN | POLLHUP | POLLERR)) != 0)
        {
          ws_read_client(ws, c);

          if (c->fd < 0)
            {
              continue;
            }
        }

      if ((fds[i].revents & POLLOUT) != 0)
        {
          ws_flush(ws, c);
        }
    }
}
