      fds[0].fd = camfd;
      fds[0].events = POLLIN;
      fds[0].revents = 0;
      ncam = 1;
    }

  n = ncam + camenc_ws_fds(&g_ws, &fds[ncam], CAMENC_WAIT_FDS - ncam);

  mark = camenc_now_us();

  if (poll(fds, (nfds_t)n, ncam != 0 ? CAMENC_WAIT_MS : 0) < 0 &&
      errno != EINTR)
